python3 - <<'PY'
import json, urllib.request, ssl
url = "https://mcp.sublime.app/mcp?token=2e5be791aa9ef02664d06417d8090d5923264b8aab8122bf724187e9def8ab7f"
req = urllib.request.Request(
    url,
    data=json.dumps({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "initialize",
        "params": {
            "protocolVersion": "2025-03-26",
            "capabilities": {},
            "clientInfo": {"name": "grok-probe", "version": "0"}
        }
    }).encode(),
    headers={
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
    },
    method="POST",
)
try:
    with urllib.request.urlopen(req, timeout=15) as resp:
        print("status", resp.status)
        print("headers", dict(resp.headers))
        body = resp.read(2000)
        print("body", body[:1500])
except Exception as e:
    print(type(e).__name__, e)
    if hasattr(e, "code"):
        print("http", e.code)
    if hasattr(e, "read"):
        print("errbody", e.read(1500))
PY

